// live2d.min.js - Live2D Cubism 4 Runtime Shim
// This file provides a compatibility layer for pixi-live2d-display

// The global Live2D object is expected by pixi-live2d-display for Cubism 2 compatibility.
window.Live2D = {
    // This is the key part. It tells the pixi plugin that a Cubism 4 core is available.
    // The pixi-live2d-display plugin will check for this before falling back to Cubism 2.
    Cubism4: window.Live2DCubismCore
};

// You must also ensure Live2DCubismCore is loaded globally before pixi-live2d-display
// In your index.html:
